import heapq
import sys

class Solution:
    def findShortestPath(self, master: 'GridMaster') -> int:
        sys.setrecursionlimit(20000)
        DIRS = {'U': (-1, 0), 'D': (1, 0), 'L': (0, -1), 'R': (0, 1)}
        OPP = {'U': 'D', 'D': 'U', 'L': 'R', 'R': 'L'}
        cost = {(0, 0): 0}
        target = []

        def dfs(x, y):
            if master.isTarget():
                target.append((x, y))
            for d, (dx, dy) in DIRS.items():
                nx, ny = x + dx, y + dy
                if (nx, ny) not in cost and master.canMove(d):
                    cost[(nx, ny)] = master.move(d)
                    dfs(nx, ny)
                    master.move(OPP[d])

        dfs(0, 0)
        if not target:
            return -1
        tx, ty = target[0]
        heap = [(0, 0, 0)]
        dist = {}
        while heap:
            d, x, y = heapq.heappop(heap)
            if (x, y) == (tx, ty):
                return d
            if d > dist.get((x, y), float('inf')):
                continue
            for dx, dy in DIRS.values():
                nx, ny = x + dx, y + dy
                if (nx, ny) in cost:
                    nd = d + cost[(nx, ny)]
                    if nd < dist.get((nx, ny), float('inf')):
                        dist[(nx, ny)] = nd
                        heapq.heappush(heap, (nd, nx, ny))
        return -1

