        const string dirs = "UDLR", opp = "DURL";
        map<pair<int,int>, int> cost;
        cost[{0, 0}] = 0;
        pair<int,int> target{-1000, -1000};
        function<void(int,int)> dfs = [&](int x, int y) {
            if (master.isTarget()) target = {x, y};
            for (int i = 0; i < 4; i++) {
                int nx = x + dx[i], ny = y + dy[i];
                if (!cost.count({nx, ny}) && master.canMove(dirs[i])) {
                    cost[{nx, ny}] = master.move(dirs[i]);
                    dfs(nx, ny);
                    master.move(opp[i]);
                }
            }
        };
        dfs(0, 0);
        if (target.first == -1000) return -1;
        priority_queue<tuple<int,int,int>, vector<tuple<int,int,int>>, greater<tuple<int,int,int>>> pq;
        pq.push({0, 0, 0});
        map<pair<int,int>, int> dist;
        while (!pq.empty()) {
            auto [d, x, y] = pq.top(); pq.pop();
            if (make_pair(x, y) == target) return d;
            auto held = dist.find({x, y});
            if (held != dist.end() && d > held->second) continue;
            for (int i = 0; i < 4; i++) {
                int nx = x + dx[i], ny = y + dy[i];
                auto w = cost.find({nx, ny});
                if (w == cost.end()) continue;
                int nd = d + w->second;
                auto it = dist.find({nx, ny});
                if (it == dist.end() || nd < it->second) {
                    dist[{nx, ny}] = nd;
                    pq.push({nd, nx, ny});
                }
            }
        }
        return -1;
    }
};

