import java.util.*;

class Solution {
    static final int[] DX = {-1, 1, 0, 0}, DY = {0, 0, -1, 1};
    static final char[] DIR = {'U', 'D', 'L', 'R'}, OPP = {'D', 'U', 'R', 'L'};
    Map<Integer, Integer> cost = new HashMap<>();
    int tx = Integer.MIN_VALUE, ty;

    private int key(int x, int y) {
        return (x + 150) * 400 + (y + 150);
    }

    private void dfs(int x, int y, GridMaster master) {
        if (master.isTarget()) { tx = x; ty = y; }
        for (int i = 0; i < 4; i++) {
            int nx = x + DX[i], ny = y + DY[i];
            if (!cost.containsKey(key(nx, ny)) && master.canMove(DIR[i])) {
                cost.put(key(nx, ny), master.move(DIR[i]));
                dfs(nx, ny, master);
                master.move(OPP[i]);
            }
        }
    }

    public int findShortestPath(GridMaster master) {
        cost.put(key(0, 0), 0);
        dfs(0, 0, master);
        if (tx == Integer.MIN_VALUE) return -1;
        PriorityQueue<long[]> pq =
            new PriorityQueue<>((a, b2) -> Long.compare(a[0], b2[0]));
        Map<Integer, Integer> dist = new HashMap<>();
        pq.offer(new long[]{0, 0, 0});
        while (!pq.isEmpty()) {
            long[] cur = pq.poll();
            int d = (int) cur[0], x = (int) cur[1], y = (int) cur[2];
            if (x == tx && y == ty) return d;
            Integer held = dist.get(key(x, y));
            if (held != null && d > held) continue;
            for (int i = 0; i < 4; i++) {
                int nx = x + DX[i], ny = y + DY[i];
                Integer w = cost.get(key(nx, ny));
                if (w == null) continue;
                int nd = d + w;
                Integer old = dist.get(key(nx, ny));
                if (old == null || nd < old) {
                    dist.put(key(nx, ny), nd);
                    pq.offer(new long[]{nd, nx, ny});
                }
            }
        }
        return -1;
    }
}

