var findShortestPath = function(master) {
    const DX = [-1, 1, 0, 0], DY = [0, 0, -1, 1];
    const DIR = ['U', 'D', 'L', 'R'], OPP = ['D', 'U', 'R', 'L'];
    const key = (x, y) => (x + 200) * 1000 + (y + 200);
    const cost = new Map([[key(0, 0), 0]]);
    let target = null;
    const stack = [[0, 0, 0, -1]];
    while (stack.length) {
        const fr = stack[stack.length - 1];
        if (master.isTarget()) target = [fr[0], fr[1]];
        let advanced = false;
        while (fr[2] < 4) {
            const j = fr[2]++;
            const nx = fr[0] + DX[j], ny = fr[1] + DY[j];
            if (!cost.has(key(nx, ny)) && master.canMove(DIR[j])) {
                cost.set(key(nx, ny), master.move(DIR[j]));
                stack.push([nx, ny, 0, j]);
                advanced = true;
                break;
            }
        }
        if (!advanced) {
            stack.pop();
            if (stack.length) master.move(OPP[fr[3]]);
        }
    }
    if (target === null) return -1;
    const pq = [[0, 0, 0]];
    const push = (item) => {
        pq.push(item);
        let i = pq.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (pq[p][0] <= pq[i][0]) break;
            const tmp = pq[p]; pq[p] = pq[i]; pq[i] = tmp;
            i = p;
        }
    };
    const pop = () => {
        const top = pq[0];
        const last = pq.pop();
        if (pq.length) {
            pq[0] = last;
            let i = 0;
            for (;;) {
                const l = 2 * i + 1, r = l + 1;
                let m = i;
                if (l < pq.length && pq[l][0] < pq[m][0]) m = l;
                if (r < pq.length && pq[r][0] < pq[m][0]) m = r;
                if (m === i) break;
                const tmp = pq[m]; pq[m] = pq[i]; pq[i] = tmp;
                i = m;
            }
        }
        return top;
    };
    const dist = new Map();
    while (pq.length) {
        const [d, x, y] = pop();
        if (x === target[0] && y === target[1]) return d;
        const held = dist.get(key(x, y));
        if (held !== undefined && d > held) continue;
        for (let i = 0; i < 4; i++) {
            const nx = x + DX[i], ny = y + DY[i];
            const w = cost.get(key(nx, ny));
            if (w === undefined) continue;
            const nd = d + w;
            const old = dist.get(key(nx, ny));
            if (old === undefined || nd < old) {
                dist.set(key(nx, ny), nd);
                push([nd, nx, ny]);
            }
        }
    }
    return -1;
};

