        target = []

        def dfs(x, y):
            if master.isTarget():
                target.append((x, y))
            for d, (dx, dy) in DIRS.items():
                nx, ny = x + dx, y + dy
                if (nx, ny) not in cost and master.canMove(d):
                    cost[(nx, ny)] = master.move(d)
                    dfs(nx, ny)
                    master.move(OPP[d])

        dfs(0, 0)
        if not target:
            return -1
        tx, ty = target[0]
        buckets = defaultdict(list)
        dist = {(0, 0): 0}
        buckets[0].append((0, 0))
        pending, d = 1, 0
        while pending:
            for x, y in buckets.pop(d, []):
                pending -= 1
                if dist.get((x, y), 1 << 60) < d:
                    continue
                if (x, y) == (tx, ty):
                    return d
                for dx, dy in DIRS.values():
                    nx, ny = x + dx, y + dy
                    if (nx, ny) in cost:
